import { useState } from 'react';

type Props = { options: string[]; onChange?: (v: string) => void };

export default function {{component_name}}({ options, onChange }: Props) {
  const [active, setActive] = useState(options[0]);
  return (
    <div className="inline-flex rounded border">
      {options.map((o) => (
        <button
          key={o}
          onClick={() => { setActive(o); onChange?.(o); }}
          className={`px-3 py-1 ${active === o ? 'bg-blue-600 text-white' : 'bg-white'}`}
        >
          {o}
        </button>
      ))}
    </div>
  );
}
